package com.sorenkai.core.model.community.discussions

import com.sorenkai.common.util.newId
import com.sorenkai.core.model.auth.UID
import kotlinx.serialization.Serializable
import kotlin.time.ExperimentalTime
import kotlin.time.Instant

/**
 * Represents a discussion item in the system, which can be either
 * a top-level post or a comment on another post.
 *
 * @property id Unique identifier for the discussion (generated by [newId]).
 * @property kind Whether this discussion is a [Kind.POST] (top-level thread)
 *                or a [Kind.COMMENT] (reply to another discussion).
 * @property writingId Optional ID of a writing that this discussion is linked to.
 *                       Only set for posts that reference published writings.
 * @property parentId Optional identifier of the parent discussion if this is a comment.
 * @property userId The UID of the user who created the discussion.
 * @property body The main text body of the post/comment (1–5000 chars enforced at validation).
 * @property createdAt Timestamp when the discussion was first created.
 * @property updatedAt Timestamp when the discussion was last updated.
 */
@Serializable
@OptIn(ExperimentalTime::class)
data class Discussion(
    val id: String = newId(),
    val kind: Kind,
    val writingId: String? = null,
    val parentId: String? = null,
    val userId: String,
    val body: String,
    val lang: String = "en",
    // Moderation
    val status: DiscussionsStatus = DiscussionsStatus.VISIBLE,
    val reason: String? = null,
    val moderatedBy: UID? = null,
    val moderatedAt: Instant? = null,
    // Reporting
    val reportedBy: Set<UID> = emptySet(),
    // Admin
    val isPinned: Boolean = false,
    val isLocked: Boolean = false,
    val createdAt: Instant,
    val updatedAt: Instant? = null,
) {
    val isDeleted: Boolean
        get() = status == DiscussionsStatus.DELETED_BY_AUTHOR || status == DiscussionsStatus.DELETED_BY_MODERATOR

    val isHidden: Boolean
        get() =
            status == DiscussionsStatus.HIDDEN_BY_REPORTS ||
                status == DiscussionsStatus.HIDDEN_BY_MODERATOR ||
                isDeleted

    val isVisible: Boolean
        get() = !isHidden
}
